from collections import Counter
import math
import copy

def check_termination(numbers):
    if not numbers:
        return True

    S = sum(numbers)
    if S == 0:
        return True

    z = max(numbers)
    S_other = S - z

    return z > S_other

def find_n_final_sim(N0):
    # Initial state: N0 copies of 1
    current_numbers = [1] * N0

    MAX_ROUNDS = N0 * 5 # Increased safety margin for rounds

    for round_num in range(1, MAX_ROUNDS + 1):
        if check_termination(current_numbers):
            return len(current_numbers)

        # Player A's move: Choose x, y such that z=x+y is minimized (Greedy approach for max N_final)

        potential_moves = []

        # Use unique values to find all possible pairs (x, y) where x <= y
        unique_values = sorted(list(set(current_numbers)))

        # Iterate through all unique pairs of values
        for i in range(len(unique_values)):
            for j in range(i, len(unique_values)):
                x = unique_values[i]
                y = unique_values[j]
                z = x + y

                # Calculate the resulting state after removing x and y and adding z

                # Start with a mutable copy of the current numbers
                temp_list = list(current_numbers)

                # Remove one instance of x and one instance of y. 
                # list.remove() removes the first occurrence.
                try:
                    temp_list.remove(x)
                    temp_list.remove(y)

                    new_list = temp_list + [z]

                    # Record the move and resulting state
                    potential_moves.append({
                        'z': z, 
                        'new_list': new_list, 
                        'cost': z # Minimizing z is the heuristic for maximizing N_final
                    })
                except ValueError:
                    # This should not happen if x and y are drawn from current_numbers
                    continue

        if not potential_moves:
             return len(current_numbers)

        # A chooses the move that minimizes the resulting z
        best_move = min(potential_moves, key=lambda m: m['cost'])

        current_numbers = best_move['new_list']

    return len(current_numbers)

results = {}
for N0 in range(3, 11):
    results[N0] = find_n_final_sim(N0)

print("N0 | N_final")
print("----------------")
for N0, N_final in results.items():
    print(f"{N0:2} | {N_final}")
